from flask import Flask, render_template_string, request
app = Flask(__name__)

@app.route('/dinner', methods=['GET', 'POST'])
def dinner():
    if request.method == 'POST':
        print('Message from guest: {}'.format(request.form['message']))
        return render_template_string('Dinner party begins!')

    return render_template_string('Dinner party scheduled!')
